import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "liblap4.so"))
_f = _lib.solve_lap4
_f.restype = ctypes.c_int
_f.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_double]


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if M.shape == (n, n) and b.shape[0] == n and n > 1:
            a0 = a[0]
            if (a == a0).all() and (b == a0).all():
                c4r = np.empty(n, dtype=np.int32)
                G = np.empty((n, n))
                if _f(n, M.ctypes.data, c4r.ctypes.data, G.ctypes.data, a0) == 0:
