#include <stdlib.h>
#include <math.h>
#include <string.h>
/* heap of (key, col) with lazy deletion */
typedef struct { double k; int j; } HE;
static void hpush(HE *h, int *sz, double k, int j){
  int i=(*sz)++; while(i>0){int p=(i-1)>>1; if(h[p].k<=k)break; h[i]=h[p]; i=p;} h[i].k=k; h[i].j=j;}
static HE hpop(HE *h, int *sz){
  HE top=h[0]; HE last=h[--(*sz)]; int n=*sz, i=0;
  while(1){int c=2*i+1; if(c>=n)break; if(c+1<n && h[c+1].k<h[c].k)c++; if(h[c].k>=last.k)break; h[i]=h[c]; i=c;}
  if(n>0) h[i]=last; return top;}

/* sparse SAP. adjacency CSR: start[n+1], adj cols, w costs. returns 0 ok, -1 infeasible */
static int sap(int n, const int *start, const int *adj, const double *w,
               double *u, double *v, int *col4row, int *row4col){
  double *spc=malloc(n*sizeof(double)); int *path=malloc(n*sizeof(int));
  char *SC=calloc(n,1); int *trows=malloc(n*sizeof(int)); int *tcols=malloc(n*sizeof(int));
  int *seen=malloc(n*sizeof(int)); int nseen;
  HE *h=malloc((size_t)(start[n]+n+1)*sizeof(HE));
  for(int j=0;j<n;j++){spc[j]=INFINITY;row4col[j]=-1;}
  for(int i=0;i<n;i++){col4row[i]=-1;u[i]=0;}
  int ret=0;
  for(int cur=0;cur<n;cur++){
    int i=cur, hs=0, nr=0, nc=0; nseen=0; double minVal=0; int sink=-1;
    while(sink==-1){
      trows[nr++]=i;
      for(int e=start[i];e<start[i+1];e++){int j=adj[e]; if(SC[j])continue;
        double r=minVal+w[e]-u[i]-v[j];
        if(r<spc[j]){ if(spc[j]==INFINITY) seen[nseen++]=j; spc[j]=r; path[j]=i; hpush(h,&hs,r,j);} }
      int j=-1;
      while(hs>0){HE t=hpop(h,&hs); if(SC[t.j]||t.k!=spc[t.j])continue; j=t.j; break;}
      if(j<0){ret=-1;goto done;}
      minVal=spc[j]; SC[j]=1; tcols[nc++]=j;
      if(row4col[j]==-1) sink=j; else i=row4col[j];
    }
    u[cur]+=minVal;
    for(int a=1;a<nr;a++){int r=trows[a]; u[r]+=minVal-spc[col4row[r]];}
    for(int a=0;a<nc;a++){int j=tcols[a]; v[j]-=minVal-spc[j];}
    {int j=sink; while(1){int r=path[j]; row4col[j]=r; int t=col4row[r]; col4row[r]=j; j=t; if(r==cur)break;}}
    for(int a=0;a<nseen;a++){spc[seen[a]]=INFINITY; SC[seen[a]]=0;}
  }
done:
  free(spc);free(path);free(SC);free(trows);free(tcols);free(seen);free(h);
  return ret;
}

/* C dense n x n. returns 0 on success with col4row filled */
int solve_lap(int n, const double *C, int k, int *col4row){
  int *row4col=malloc(n*sizeof(int)); double *u=malloc(n*sizeof(double)); double *v=malloc(n*sizeof(double));
  char *mark=calloc((size_t)n*n,1);
  int ret=-1;
  if(k>n)k=n;
  /* row kNN */
  double *bk=malloc(k*sizeof(double)); int *bj=malloc(k*sizeof(int));
  for(int i=0;i<n;i++){const double *c=C+(size_t)i*n; int cnt=0;
    for(int j=0;j<n;j++){double x=c[j];
      if(cnt<k){int p=cnt++; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bj[p]=bj[p-1];p--;} bk[p]=x;bj[p]=j;}
      else if(x<bk[k-1]){int p=k-1; while(p>0&&bk[p-1]>x){bk[p]=bk[p-1];bj[p]=bj[p-1];p--;} bk[p]=x;bj[p]=j;}}
    for(int a=0;a<k;a++) mark[(size_t)i*n+bj[a]]=1;}
  /* col kNN */
  {double *ck=malloc((size_t)k*n*sizeof(double)); int *ci=malloc((size_t)k*n*sizeof(int)); int *cc=calloc(n,sizeof(int));
   for(int i=0;i<n;i++){const double *c=C+(size_t)i*n;
     for(int j=0;j<n;j++){double x=c[j]; double *K=ck+(size_t)j*k; int *I=ci+(size_t)j*k; int p;
       if(cc[j]<k) p=cc[j]++; else if(x<K[k-1]) p=k-1; else continue;
       while(p>0&&K[p-1]>x){K[p]=K[p-1];I[p]=I[p-1];p--;} K[p]=x;I[p]=i;}}
   for(int j=0;j<n;j++) for(int a=0;a<cc[j];a++) mark[(size_t)ci[(size_t)j*k+a]*n+j]=1;
   free(ck);free(ci);free(cc);}
  /* v init: column minima (feasible) */
  for(int j=0;j<n;j++) v[j]=INFINITY;
  for(int i=0;i<n;i++){const double *c=C+(size_t)i*n; for(int j=0;j<n;j++) if(c[j]<v[j]) v[j]=c[j];}
  int *start=malloc((n+1)*sizeof(int));
  for(int iter=0;iter<20;iter++){
    size_t E=0; for(size_t t=0;t<(size_t)n*n;t++) E+=mark[t];
    int *adj=malloc(E*sizeof(int)); double *w=malloc(E*sizeof(double));
    size_t e=0;
    for(int i=0;i<n;i++){start[i]=e; for(int j=0;j<n;j++) if(mark[(size_t)i*n+j]){adj[e]=j;w[e]=C[(size_t)i*n+j];e++;}}
    start[n]=e;
    for(int j=0;j<n;j++) v[j]=INFINITY;
    for(int i=0;i<n;i++){const double *c=C+(size_t)i*n; for(int j=0;j<n;j++) if(c[j]<v[j]) v[j]=c[j];}
    int r=sap(n,start,adj,w,u,v,col4row,row4col);
    free(adj);free(w);
    if(r!=0){ /* infeasible sparse: densify */ memset(mark,1,(size_t)n*n); continue;}
    int viol=0;
    for(int i=0;i<n;i++){const double *c=C+(size_t)i*n; double ui=u[i];
      for(int j=0;j<n;j++){ if(c[j]-ui-v[j] < -1e-12){ if(!mark[(size_t)i*n+j]){mark[(size_t)i*n+j]=1;viol++;} } }}
    if(viol==0){ret=0;break;}
  }
  free(start);free(bk);free(bj);free(mark);free(row4col);free(u);free(v);
  return ret;
}
