static void knn_rows(int n, const double *C, int k, char *mark){
  double *bk=malloc(k*sizeof(double)); int *bj=malloc(k*sizeof(int));
  for(int i=0;i<n;i++){const double *c=C+(size_t)i*n; int cnt=0;
    for(int j=0;j<n;j++){double x=c[j]; int p;
